# -*- coding: utf-8 -*-
"""ВІДСІВ-1 (02.10): (а) нижче смуги — у пулі з позначкою, суд ставить K-KOH-07 без пояснення; (б) замша в пулі за
погодою. Каталог_повний. Запуск із `джерела`: python3 проби/відсів1_суд.py (на main — те саме: друкує ДО)."""
import json, sys, collections; sys.path.insert(0, ".")
import feed as Ф; Ф.каталог_на_диску("каталог_повний.xml")
import bridge as B, pipeline as PL, композитор_придатні as КП, фід_каталог as ФК, fit as ПС, colorspace as cs, аксесуари_погода as АП
к = ФК._прочитати_каталог("каталог_повний.xml", 0)["каталог"]; за = {r["id"]: r for r in к}
СЦ = dict(співбесіда=dict(нагода="співбесіда", місце="співбесіда", ошатність=[6, 8]),
          похорон=dict(нагода="траур", місце="похорон", ошатність=[6, 7]), театр=dict(нагода="театр", місце="театр", ошатність=[4, 6]))
for н, сц in СЦ.items():
    лиш, геть, _ = КП._поза_сценою(к, сц)
    print("(а) пул %-10s каталог %d → лишилось %d (з позначкою нижче смуги %d) · знято %d" % (
        н, len(к), len(лиш), sum(1 for r in лиш if r.get("_нижче_смуги")), len(геть)))
сумки = [r for r in к if r.get("слот") == "сумка" and КП.нижче_смуги(r, 6) and isinstance(r.get("формальність_фото"), int) and r["формальність_фото"] >= 6]
print("(а) рядок 512: сумок «нижче смуги» похорону 6–7 з балом фото ≥ 6: %d · серед них чорних шкіряних: %d" % (len(сумки),
      sum(1 for r in сумки if "чорн" in str(r.get("колір_назва")) and "шкір" in str(r.get("матеріал")).lower())))
вх = json.load(open("стенд_вх.json", encoding="utf-8")); T = ПС.тіло(float(вх["зріст"]), {k: float(v) for k, v in вх["обхвати"].items()})
F = cs.features(cs.hx(вх["шкіра"]), cs.hx(вх["волосся"][0]), cs.hx(вх["очі"]))
for підпис, сц, бж in (("дощ +10", dict(опади="дощ", темп_c=10), None), ("мокрий сніг 0 °C (сіль)", dict(опади="мокрий_сніг", темп_c=0), None),
                       ("злива +12", dict(опади="злива", темп_c=12), None), ("злива + вона просить замшу", dict(опади="злива", темп_c=12), "замша"),
                       ("сухо +12", dict(опади="ні", темп_c=12), None)):
    d = dict(вх, сценарій=dict(вх["сценарій"], нагода="щоденне", місце="місто", година=11, дрес_код=None, **сц))
    if бж: d["паспорт"] = dict(бажання=["замшеві черевики"], бажання_коди=[dict(слот="взуття", тканина=бж, фраза="замшеві черевики")])
    r = json.loads(B.виклик("запити", json.dumps(d, ensure_ascii=False))); кат = {c["id"]: c for c in B.каталог_останнього_пакета()}
    вз = r["кандидати"].get("взуття", [])
    print("(б) %-26s взуття в пулі %d, з них замша/нубук/велюр %d · знято вето вологи %s" % (підпис, len(вз),
          sum(1 for c in вз if АП.відмовляє_у_волозі(кат.get(c["id"]) or c)), (r.get("відсічено") or {}).get("лічба", {}).get("wet_weather_material_veto", 0)))
r = json.loads(B.виклик("запити", json.dumps(dict(вх, сценарій=dict(вх["сценарій"], ошатність=[6, 8])), ensure_ascii=False)))
print("(а) пул моделі «офіс 6–8»: речей %d, з них нижче смуги %d" % (sum(map(len, r["кандидати"].values())), sum(
      1 for v in r["кандидати"].values() for x in v if x.get("_нижче_смуги") or КП.нижче_смуги(кат.get(x["id"]) or x, 6))))
к = B.каталог_останнього_пакета(); пер = lambda с: next(r for r in к if r.get("слот") == с and not КП.нижче_смуги(r, 6))
кеди = next(r for r in к if r.get("тип") == "кеди"); ід = [пер("верх")["id"], пер("низ")["id"], кеди["id"]]
for підпис, розр in (("без пояснення", []), ("з поясненням", [dict(річ="#1·03", ід=кеди["id"], чому="навмисно: вона просила зручне", текст="кеди — навмисно")])):
    в = PL.перевірити_від_моделі(ід, F, к, T, dict(СЦ["похорон"], темп_c=18), розриви=розр)
    з = [z for z in в["знахідки"] if z.get("правило") == "K-KOH-07"]
    print("(а) суд, похорон, образ із кедами (%s, %s): K-KOH-07 %s" % (кеди["id"], підпис, [
        (z.get("сила"), z.get("регістр"), z.get("сила_нп"), z.get("пояснено")) for z in з] or "нема"))
